const D = { energy: .6, scale: 1, density: .5, wear: .5, speed: 1, hue: 28, x: .5, y: .94, alpha: 1, style: 'canvas', act: 'trade', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:(v>b?b:v), md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const sd=P.seed|0;
const fr=i=>{const s=Math.sin(i*127.1+sd*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lb==null||K.beat<S.lb)S.lb=K.beat; S.lb=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style;
const tarp=(sty==='tarp'), lant=(sty==='lantern'), riso=(sty==='riso'), noct=(sty==='nocturne');
const H=md(P.hue,360), AL=cl(P.alpha,0,1);
const en=cl(P.energy,0,1), sc=cl(P.scale,.3,2.4), dens=cl(P.density,0,1);
const spd=cl(P.speed,.1,4), wr=cl(P.wear,0,1.4), act=P.act;
const bx=cl(P.x,.05,.95)*W, by=cl(P.y,.4,1.12)*Hh;

const NS=Math.max(2,Math.round(2+dens*3));      // stalls across
const RH=u*.52*sc;                              // stall height (frame + awning)
const SW=RH*.86;                                // stall width
const RW=SW*NS, x0=bx-RW*.5, yTop=by-RH;
const CNT=by-RH*.36;                            // counter height

S.bass=(S.bass||0)*.85+(A.bass||0)*.15;
S.tre =(S.tre ||0)*.85+(A.treble||0)*.15;
const T=K.t*spd;
const glow=(.30+.80*en)*(.55+.5*K.intensity)+S.bass*.30;
const kick=Math.min(1,K.pulse*(.5+.5*K.intensity)+S.bass*.7);

// ---- wind: three incommensurate rates, so cloth NEVER returns to a pose ----
const wind=(q,ph)=>(.55*Math.sin(T*.83+q+ph)+.28*Math.sin(T*1.41+q*1.7+ph*.6)+.17*Math.sin(T*2.13+q*.5));
let gust=.30+.55*en;
if(act==='shutter') gust*=.30; else if(act==='gust') gust*=1.5+.5*kick;

// ---- the festoon: a catenary of bulbs slung across the whole row -----------
// swings on two incommensurate rates + a slow precession — never re-phases
const fsw=gust*(.42*Math.sin(T*.51)+.22*Math.sin(T*.97+1.3)+.13*Math.sin(T*.187+.6));
const fy0=yTop-RH*.10, sag=RH*.20;
const festoon=fx=>{
  const q=(fx-x0)/Math.max(1,RW);
  return fy0+Math.sin(q*Math.PI)*sag*(1+.16*Math.sin(T*.23))+fsw*RH*.05*Math.sin(q*Math.PI*1.3);
};
const NBu=Math.max(3,Math.round(5+dens*9));

function plan(){
  const st=[];
  for(let i=0;i<NS;i++){
    st.push({ x:x0+i*SW, dep:fr(i*5.1), lit:fr(i*5.1+1)>.28,
      food:fr(i*5.1+2)>.62, aw:.55+fr(i*5.1+3)*.4, stripe:2+Math.round(fr(i*5.1+4)*3) });
  }
  return st;
}

const bkey=[W,Hh,sty,sd,Math.round(H),Math.round(sc*40),NS,Math.round(wr*6),Math.round(dens*8),Math.round(P.x*120),Math.round(P.y*120)].join('|');
