    // ---- trestle counter: boards on a frame, crates stacked beneath -------
    const cH=by-CNT;
    g.fill(riso?md(H+186,360):md(H+8,360),riso?62:(noct?8:34),cl((noct?16:26)*near,3,70),96);
    g.rect(sx+SW*.06,CNT,SW*.88,Math.max(1.6,RH*.020));
    g.fill(riso?md(H+186,360):md(H+8,360),riso?54:(noct?6:30),cl((noct?30:44)*near,3,84),70);
    g.rect(sx+SW*.06,CNT,SW*.88,Math.max(.8,RH*.007));
