      g.fill(riso?md(H+186,360):md(H+6,360),riso?50:(noct?6:28),cl((noct?7:11)*near*(1+fr(i*9+k+3)*.8),2,40),94);
      g.rect(cx2,cy2,cw,ch);
      g.fill(riso?md(H+186,360):md(H+6,360),riso?44:(noct?5:24),cl((noct?12:19)*near,2,50),70);
      g.rect(cx2,cy2,cw,Math.max(.8,ch*.10));
      for(let q=0;q<3;q++){ g.fill(0,0,0,26);
        g.rect(cx2,cy2+ch*(.3+q*.22),cw,Math.max(.6,ch*.04)); }
    }
    // produce trays on the counter — colour, but broken up, never a flat block
    if(!s.food){
      for(let k=0;k<Math.round(3+dens*4);k++){
        const tx=sx+SW*(.09+.80*fr(i*13+k)), tw=SW*(.11+fr(i*13+k+1)*.09);
        const th=RH*.030, ty=CNT-th;
        const ph2=riso?md(H+186,360):md(H+fr(i*13+k+2)*300,360);
        g.fill(ph2,riso?60:(noct?8:52),cl((noct?22:38)*near,3,72),92);
        g.rect(tx,ty,tw,th);
        for(let q=0;q<7;q++){          // the goods themselves: stippled, not a fill
          g.fill(ph2,riso?66:(noct?10:64),cl((noct?30:56)*near*(.7+fr(i*13+k+q+5)*.6),3,88),86);
          g.ellipse(tx+tw*(.1+fr(i*13+k+q+6)*.8),ty+th*.3,tw*.14,tw*.12);
        }
