    // ---- the frame: four uprights + a top rail + the awning rake ----------
    pole(sx+SW*.07,by,sx+SW*.07,yTop,PW,near);
    pole(sx+SW*.93,by,sx+SW*.93,yTop,PW,near);
    pole(sx+SW*.07,yTop,sx+SW*.93,yTop,PW*.9,near);
    pole(sx+SW*.20,CNT,sx+SW*.20,by,PW*.7,near);
    pole(sx+SW*.80,CNT,sx+SW*.80,by,PW*.7,near);
    // gable spine the awning hangs off
    pole(sx+SW*.07,yTop,sx+SW*.5,yTop-RH*.10,PW*.8,near);
    pole(sx+SW*.93,yTop,sx+SW*.5,yTop-RH*.10,PW*.8,near);
    // ---- signboard over the counter --------------------------------------
    if(fr(i*17)>.45){
      const sgy=CNT-RH*.20, sgh=RH*.055;
      g.fill(riso?md(H+186,360):md(H+170,360),riso?52:(noct?8:22),cl((noct?12:18)*near,2,50),92);
