  }
  // ---- ground: trodden dirt, spilt straw, wet patches under the stalls ----
  const NGm=Math.round((26+dens*30)*(1+wr*.6));
  for(let k=0;k<NGm;k++){
    const gx=x0-SW*.2+fr(k*3.1)*(RW+SW*.4), gy=by+fr(k*3.1+1)*RH*.06;
    g.fill(riso?md(H+186,360):md(H+4,360),riso?48:(noct?6:26),cl((noct?8:13)*(.5+fr(k*3.1+2)),2,40),44);
    g.ellipse(gx,gy,RH*.02*(.5+fr(k*3.1+3)*2.6),RH*.007*(.5+fr(k*3.1+4)*1.6));
  }
  S.base=g; S.bk=bkey;
}
if(!S.stalls) S.stalls=plan();
const st=S.stalls;
image(S.base,0,0);

const dc=drawingContext, oldOp=dc.globalCompositeOperation;

// ---- the awnings: real cloth, the piece's motor ---------------------------
// striped canvas bellying and luffing — this is what makes the row alive
{
  noStroke();
  const cols=8, rows=4;
  for(let i=0;i<st.length;i++){
    const s=st[i], sx=s.x, near=1-s.dep*.5;
    const aTop=yTop-RH*.10, aFront=yTop+RH*.02;
    const depth=SW*.52*s.aw;
    const amp=RH*(.02+.075*gust);
    for(let c=0;c<cols;c++){
      const f0=c/cols, f1=(c+1)/cols;
      const inStripe=(Math.floor(c/1)%2)===0;
      let h2,s2,b2;
      if(riso){ h2=inStripe?md(H,360):md(H+186,360); s2=inStripe?72:56; b2=inStripe?74:50; }
      else if(tarp){ h2=md(H+178,360); s2=inStripe?54:46; b2=inStripe?46:34; }
      else if(lant){ h2=inStripe?md(H+2,360):md(H+14,360); s2=inStripe?18:30; b2=inStripe?82:66; }
      else if(noct){ h2=md(H+178,360); s2=8; b2=inStripe?34:24; }
      else { h2=inStripe?md(H+4,360):md(H+184,360); s2=inStripe?62:34; b2=inStripe?62:74; }
      beginShape();
      for(let r=0;r<=rows;r++){
        const fy=r/rows;
        const w0=wind(f0*2.4,i*1.9)*amp*(.35+fy);
        vertex(sx+SW*(.07+f0*.86)+w0*.5, aTop+(aFront-aTop)*fy+fy*depth*.9+w0);
      }
      for(let r=rows;r>=0;r--){
        const fy=r/rows;
        const w1=wind(f1*2.4,i*1.9)*amp*(.35+fy);
        vertex(sx+SW*(.07+f1*.86)+w1*.5, aTop+(aFront-aTop)*fy+fy*depth*.9+w1);
      }
      fill(h2,s2,cl(b2*(.5+.6*near),3,92),(riso?88:94)*AL);
      endShape(CLOSE);
      // the fold shadow where the cloth bellies — cloth is never flat
      const shd=cl(.5+.5*wind(f0*2.4+.5,i*1.9),0,1);
      fill(h2,s2,cl(b2*.3,2,40),cl(30*shd,0,44)*AL);
      beginShape();
      for(let r=0;r<=rows;r++){ const fy=r/rows;
        const w0=wind(f0*2.4,i*1.9)*amp*(.35+fy);
        vertex(sx+SW*(.07+f0*.86)+w0*.5, aTop+(aFront-aTop)*fy+fy*depth*.9+w0); }
      for(let r=rows;r>=0;r--){ const fy=r/rows;
        const w1=wind(f1*2.4,i*1.9)*amp*(.35+fy);
        vertex(sx+SW*(.07+f0*.86+ (f1-f0)*.42)+w1*.5, aTop+(aFront-aTop)*fy+fy*depth*.9+w1); }
      endShape(CLOSE);
    }
    // scalloped valance snapping along the front edge
    const vh=RH*.045;
    for(let c=0;c<cols;c++){
      const f0=c/cols;
      const w0=wind(f0*2.4,i*1.9+3.1)*amp*1.5;
      const inStripe=(c%2)===0;
      let h2,s2,b2;
      if(riso){ h2=inStripe?md(H,360):md(H+186,360); s2=70; b2=inStripe?70:46; }
      else if(tarp){ h2=md(H+178,360); s2=50; b2=40; }
      else if(lant){ h2=md(H+6,360); s2=22; b2=76; }
      else if(noct){ h2=md(H+178,360); s2=8; b2=28; }
      else { h2=inStripe?md(H+4,360):md(H+184,360); s2=inStripe?60:32; b2=inStripe?58:70; }
      fill(h2,s2,cl(b2*(.5+.6*near)*.9,3,88),92*AL);
      const vx=sx+SW*(.07+f0*.86);
      arc(vx+SW*.86/cols*.5+w0, aFront+depth*.9+w0+vh*.1, SW*.86/cols*1.02, vh*2, 0, Math.PI);
    }
  }
}

