// ---- the festoon cord + the bulbs themselves ------------------------------
{
  noFill(); stroke(md(H+178,360),12,26,64*AL); strokeWeight(Math.max(.8,RH*.0022));
  beginShape();
  for(let k=0;k<=24;k++){ const fx=x0+(k/24)*RW; vertex(fx,festoon(fx)); }
